pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 val, uint256 newVal) internal {
        try c.SetMinSum(val) {} catch { return; }
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 afterInit;
        try c.MinSum() returns (uint256 __r) { afterInit = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(newVal) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && afterInit == val && c.MinSum() == val && before == val);
    }

    function testFuzz_run(uint256 val, uint256 newVal) public {
        _run(val, newVal);
    }

    receive() external payable {}
}
